"""
  :param data: List of tuples of source sentences and fertility values
  :param maxlen: Maximum sentence length permitted
  :return: Sorted data
  """
def sortbylength(src: Any, ferts: Any = None, maxlen: Any = 10000) -> object {
    indexed_src = [(i, src[i]) for i in range(len(src))];
    sorted_indexed_src = sorted(indexed_src, key=lambda (x: Any) { -len(x[1]); });
    sorted_src = [
        item[1]
        for item in sorted_indexed_src
        if (len(item[1]) < maxlen)
    ];
    sort_order = [
        item[0]
        for item in sorted_indexed_src
        if (len(item[1]) < maxlen)
    ];
    if ferts {
        sorted_tgt = [ferts[i] for i in sort_order];
    } else {
        sorted_tgt = None;
    }
    return (sorted_src, sorted_tgt);
}

test_blocks:
test "t0" {
    assert (sortbylength(['aa', 'a', 'aaaaaaaaaa'], ['b', 'b', 'b'], 1) == ([], []));;
}

test "t1" {
    assert (sortbylength(['aa', 'a', 'aaaaaaaaaa'], ['b', 'b', 'b'], 0) == ([], []));;
}

test "t2" {
    assert (
        sortbylength(['aa', 'a', 'aaaaaaaaaa'], ['b', 'b', 'b'], 4)
        == (['aa', 'a'], ['b', 'b'])
    );;
}

test "t3" {
    assert (
        sortbylength(
            `list('this is the first sentence and this is the second'),
            `list('this is the first sentence and this is the second')
        )
        == (
            `list('this is the first sentence and this is the second'),
            `list('this is the first sentence and this is the second')
        )
    );;
}

test "t4" {
    assert (
        sortbylength(
            `list('this is the first sentence'), `list('this is the first sentence')
        )
        == (`list('this is the first sentence'), `list('this is the first sentence'))
    );;
}

test "t5" {
    assert (
        sortbylength(['aa', 'a', 'aaaaaaaaaa'], ['b', 'b', 'b'], 2) == (['a'], ['b'])
    );;
}

test "t6" {
    assert (sortbylength([("a", ), ("b", ), ("c", )], [2, 4, 1], 1) == ([], []));;
}

test "t7" {
    assert (sortbylength(["a", "b", "c"], None) == (["a", "b", "c"], None));;
}

test "t8" {
    assert (
        sortbylength(`list('hello world'), `list('world hello'))
        == (`list('hello world'), `list('world hello'))
    );;
}
